import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class ArrayListInternalsDemo {
    public static void main(String[] args) {
        // Pre-allocating capacity to avoid hidden 1.5x growth array copies
        List<String> pipeline = new ArrayList<>(10000);

        pipeline.add("Stage-1");
        pipeline.add(
            "Stage-2"
        );

        // Demonstrating fail-fast behavior
        Iterator<String> iterator = pipeline.iterator();
        while (iterator.hasNext()) {
            String stage = iterator.next();
            if (stage.equals("Stage-1")) {
                // Structural modification outside iterator triggers ConcurrentModificationException
                pipeline.add("Stage-3"); 
            }
        }
    }
}
